(n, t) = map(int, input().split())
tmp = input()
s = []
for i in range(n):
	s.append(tmp[i])
ind = n
perenos = 0
for i in range(n):
	if s[i] == '.':
		nach = i + 1
for i in range(nach, n):
	if int(s[i]) > 4:
		ind = i
		break
if ind == n:
	print(*s, sep='')
	exit()
while t > 0 and s[ind] != '.':
	if int(s[ind]) > 3:
		ind -= 1
		perenos = 1
		t -= 1
		if s[ind] == '9':
			t += 1
	else:
		s[ind] = str(int(s[ind]) + 1)
		perenos = 0
		break
if s[ind] == '.':
	ind -= 1
	while s[ind] == '9':
		s[ind] = '0'
		ind -= 1
	if ind < 0 and perenos != 0:
		print(1, end='')
		viv = 0
		while s[viv] != '.':
			print(s[viv], end='')
			viv += 1
	else:
		s[ind] = str(int(s[ind]) + perenos)
		viv = 0
		while s[viv] != '.':
			print(s[viv], end='')
			viv += 1
else:
	while s[ind] == '9' or s[ind] == '.':
		if s[ind] == '.':
			ind -= 1
			continue
		s[ind] = '0'
		ind -= 1
	s[ind] = str(int(s[ind]) + perenos)
	for i in range(ind + 1):
		print(s[i], end='')
